    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  });
}

import { describe, expect, test } from "bun:test";
import { createPlan } from "./cli";

describe("dependency planner", () => {
  test("plans deterministic layers, times, and critical path", () => {
    expect(createPlan([
      { id: "deploy", duration: 1, dependsOn: ["build"] },
      { id: "lint", duration: 2, dependsOn: [] },
      { id: "build", duration: 3, dependsOn: ["lint"] },
      { id: "docs", duration: 6, dependsOn: [] },
    ])).toEqual({
      order: ["docs", "lint", "build", "deploy"],
      layers: [["docs", "lint"], ["build"], ["deploy"]],
