#!/usr/bin/env bun

type Task = { id: string; duration: number; dependsOn: string[] };
type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

function fail(message: string): never {
  throw new Error(message);
}

function validate(input: unknown): Task[] {
  if (input === null || typeof input !== "object" || Array.isArray(input)) {
    fail("Input must be an object with a tasks array.");
  }
  const record = input as Record<string, unknown>;
  if (!Array.isArray(record.tasks)) fail("tasks must be an array.");

  const ids = new Set<string>();
  const tasks: Task[] = record.tasks.map((value, index) => {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      fail(`tasks[${index}] must be an object.`);
    }
    const task = value as Record<string, unknown>;
    if (typeof task.id !== "string" || task.id.length === 0) {
      fail(`tasks[${index}].id must be a non-empty string.`);
    }
    if (ids.has(task.id)) fail(`Duplicate task id: ${task.id}`);
    ids.add(task.id);
    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
      fail(`tasks[${index}].duration must be a finite non-negative number.`);
    }
    const dependencies = task.dependsOn === undefined ? [] : task.dependsOn;
    if (!Array.isArray(dependencies) || !dependencies.every((id) => typeof id === "string")) {
      fail(`tasks[${index}].dependsOn must be an array of strings.`);
    }
    if (new Set(dependencies).size !== dependencies.length) {
      fail(`tasks[${index}].dependsOn must contain unique ids.`);
    }
    if (dependencies.includes(task.id)) fail(`Task ${task.id} cannot depend on itself.`);
    return { id: task.id, duration: task.duration, dependsOn: dependencies as string[] };
  });

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) fail(`Task ${task.id} depends on unknown task: ${dependency}`);
    }
  }
  return tasks;
}

function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];
  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    stack.push(id);
    for (const dep of [...byId.get(id)!.dependsOn].sort()) {
      if (state.get(dep) === 1) return [...stack.slice(stack.indexOf(dep)), dep];
      if (state.get(dep) !== 2) {
        const cycle = visit(dep);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
  };
  for (const task of [...tasks].sort((a, b) => a.id.localeCompare(b.id))) {
    if (!state.has(task.id)) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
}

